$admin_title='Páginas e Configurações'; include __DIR__.'/includes/header.php'; $msg='';$erro='';
if($_SERVER['REQUEST_METHOD']==='POST'&&$pdo){if(!verify_csrf($_POST['csrf_token']??null))$erro='Token de segurança inválido.';else{$action=$_POST['action']??'settings';if($action==='settings'){foreach(['topbar_text'] as $key)save_setting($pdo,$key,trim($_POST[$key]??''));$msg='Configurações atualizadas.';}elseif($action==='page'){$id=(int)($_POST['id']??0);$titulo=trim($_POST['titulo']??'');$slug=strtolower(trim($_POST['slug']??''));$conteudo=trim($_POST['conteudo']??'');$imagem=trim($_POST['imagem']??'');$parent=(int)($_POST['parent_id']??0);$ordem=max(0,(int)($_POST['ordem']??0));$status=isset($_POST['status'])?1:0;if($titulo===''||$slug==='')$erro='Informe título e slug.';elseif($id&&$parent===$id)$erro='A página não pode ser pai dela mesma.';elseif($id)$pdo->prepare('UPDATE paginas SET titulo=?,slug=?,conteudo=?,imagem=?,parent_id=?,ordem=?,status=? WHERE id=?')->execute([$titulo,$slug,$conteudo,$imagem,$parent?:null,$ordem,$status,$id]);else$pdo->prepare('INSERT INTO paginas(titulo,slug,conteudo,imagem,parent_id,ordem,status) VALUES(?,?,?,?,?,?,?)')->execute([$titulo,$slug,$conteudo,$imagem,$parent?:null,$ordem,$status]);if(!$erro)$msg='Página salva.';}}}
if(isset($_GET['delete'])&&$pdo&&verify_csrf($_GET['token']??null)){$pdo->prepare('DELETE FROM paginas WHERE id=?')->execute([(int)$_GET['delete']]);$msg='Página excluída.';}
$edit=isset($_GET['edit'])&&$pdo?db_one($pdo,'SELECT * FROM paginas WHERE id=?',[(int)$_GET['edit']]):null;$pages=$pdo?db_rows($pdo,'SELECT * FROM paginas ORDER BY ordem,id'):[];$parents=array_filter($pages,fn($page)=>empty($page['parent_id']));
?><main class="admin-content"><div class="admin-heading"><div><h1>Páginas e configurações</h1><p class="muted">Gerencie o conteúdo público em módulos, como no WordPress e Joomla.</p></div></div><?php if($msg): ?><div class="notice success"><?= e($msg) ?></div><?php endif; ?><?php if($erro): ?><div class="notice error"><?= e($erro) ?></div><?php endif; ?><div class="admin-panel"><h2>Textos gerais</h2><form class="admin-form" method="post"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="settings"><label>Texto da barra superior<input name="topbar_text" value="<?= e(setting($pdo,'topbar_text','Bem-vindo ao Banco de Negócios!')) ?>"></label><p class="muted mb-0">O conteúdo do rodapé fica em <a href="rodape.php">Rodapé e redes sociais</a>, a seção “Amplie suas oportunidades!” em <a href="promocao.php">Promoção da home</a> e os textos do banner em <a href="beneficios.php">Textos do banner</a>.</p><button class="btn btn-primary">Salvar textos</button></form></div><div class="admin-panel page-manager"><div class="admin-heading"><div><h2>Páginas institucionais</h2><p class="muted">Use HTML básico no editor para títulos, listas, links e imagens.</p></div><a class="btn btn-outline" href="?novo=1">+ Nova página</a></div><?php if($edit||isset($_GET['novo'])): ?><form class="admin-form page-editor" method="post"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="page"><input type="hidden" name="id" value="<?= (int)($edit['id']??0) ?>"><label>Título<input name="titulo" required value="<?= e($edit['titulo']??'') ?>"></label><label>Slug<input name="slug" required pattern="[a-z0-9-]+" value="<?= e($edit['slug']??'') ?>"></label><div class="form-grid-2"><label>Página pai<select name="parent_id"><option value="0">Página principal</option><?php foreach($parents as $parent): if((int)$parent['id']!==(int)($edit['id']??0)): ?><option value="<?= (int)$parent['id'] ?>" <?= ((int)($edit['parent_id']??0)===(int)$parent['id'])?'selected':'' ?>><?= e($parent['titulo']) ?></option><?php endif; endforeach; ?></select></label><label>Ordem<input type="number" name="ordem" min="0" value="<?= (int)($edit['ordem']??0) ?>"></label></div><label>Imagem de capa (URL)<input name="imagem" value="<?= e($edit['imagem']??'') ?>" placeholder="https://... ou assets/img/capa.jpg"></label><div class="editor-toolbar" data-editor="#page-content-editor"><button type="button" data-editor-tag="<strong>|</strong>">Negrito</button><button type="button" data-editor-tag="<h2>|</h2>">Título</button><button type="button" data-editor-tag="<ul><li>|</li></ul>">Lista</button><button type="button" data-editor-image>Inserir imagem</button></div><label>Conteúdo formatado<textarea id="page-content-editor" name="conteudo" required><?= e($edit['conteudo']??'') ?></textarea><small class="muted">Você pode usar HTML básico. O botão “Inserir imagem” adiciona uma tag de imagem pelo endereço informado.</small></label><label class="check-row"><input type="checkbox" name="status" value="1" <?= (($edit['status']??1)?'checked':'') ?>> Página publicada</label><div><button class="btn btn-primary">Salvar página</button> <a class="btn btn-outline" href="configuracoes.php">Cancelar</a></div></form><?php else: ?><div class="table-responsive"><table class="admin-table"><thead><tr><th>Ordem</th><th>Título</th><th>Slug</th><th>Hierarquia</th><th>Status</th><th>Ações</th></tr></thead><tbody><?php foreach($pages as $page): ?><tr><td><?= (int)$page['ordem'] ?></td><td><?= $page['parent_id']?'↳ ':'' ?><strong><?= e($page['titulo']) ?></strong></td><td><?= e($page['slug']) ?></td><td><?= $page['parent_id']?'Subpágina':'Principal' ?></td><td><?= $page['status']?'Publicada':'Rascunho' ?></td><td><a href="?edit=<?= (int)$page['id'] ?>">Editar</a> &nbsp; <a href="?delete=<?= (int)$page['id'] ?>&token=<?= e(csrf_token()) ?>" onclick="return confirm('Excluir esta página?')">Excluir</a></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></div></main><?php include __DIR__.'/includes/footer.php'; ?>